<?php
if(!defined('ABSPATH'))exit;
function dgs_cm_form($op,$year,$extra=array()){$h='<form class="cm-form" method="post" action="'.esc_url(admin_url('admin-post.php')).'">'.wp_nonce_field('dgs_communication','cm_nonce',true,false);foreach(array_merge(array('action'=>'dgs_communication','operation'=>$op,'year'=>$year,'section'=>dgs_att_get('cm_section','sms')),$extra) as $k=>$v)$h.='<input type="hidden" name="'.esc_attr($k).'" value="'.esc_attr($v).'">';return $h;}
function dgs_cm_link($year,$section='sms',$extra=array()){return dgs_school_url('communication',$year,array_merge(array('cm_section'=>$section),$extra));}
function dgs_cm_states(){return array('draft'=>'پیش‌نمایش','queued'=>'در صف ارسال','submitting'=>'در حال ارسال','accepted'=>'پذیرفته‌شده در IPPanel','sent'=>'ارسال‌شده توسط IPPanel','failed'=>'خطای ارسال','unknown'=>'نیازمند بررسی در IPPanel','canceled'=>'لغوشده','missing_phone'=>'شماره ولی نامعتبر / خالی');}
function dgs_cm_badge($state){return '<span class="cm-badge cm-state-'.esc_attr($state).'">'.esc_html(dgs_cm_states()[$state]??$state).'</span>';}
function dgs_cm_gateway($year){
 if(!current_user_can('manage_options'))return '<p class="cm-card">کلید اتصال و پترن‌ها را مدیر اصلی سایت تنظیم می‌کند.</p>';$s=dgs_cm_config();$h='<section class="cm-card"><h3>'.dgs_portal_icon('lock').' اتصال IPPanel و پترن‌های تأییدشده</h3><p>کلید را از IPPanel ← توسعه‌دهندگان ← کلیدهای دسترسی دریافت کنید. فقط ارسال پترن فعال است؛ شماره دانش‌آموز جایگزین شماره ولی نمی‌شود.</p>'.dgs_cm_form('settings',$year,array('section'=>'gateway','revision'=>$s['revision']??0)).'<div class="cm-grid"><label>خط ارسال با پیش‌شماره ۹۸<input name="sender" dir="ltr" value="'.esc_attr($s['sender']??'').'" placeholder="+983000…"></label><label>کلید API جدید<input type="password" name="api_key" autocomplete="new-password" maxlength="512" placeholder="'.(dgs_cm_key()?'کلید ذخیره شده؛ برای حفظ، خالی بگذارید':'کلید اتصال را وارد کنید').'"></label></div><label class="cm-check"><input type="checkbox" name="remove_key" value="1"> حذف کلید ذخیره‌شده</label><label class="cm-check"><input type="checkbox" name="enabled" value="1" '.checked(!empty($s['enabled']),true,false).'> فعال‌بودن ارسال IPPanel</label><p class="cm-help">نام متغیرها باید دقیقاً مطابق پنل باشند؛ هر خط نگاشت: <bdi>نام_متغیر=منبع</bdi>. منابع مجاز: <bdi>student, class, date, month, school, message, score</bdi>. متن زیر برای پیش‌نمایش است؛ متن ارسالی واقعی را پترن تأییدشده IPPanel تعیین می‌کند.</p>';
 foreach(dgs_cm_purposes() as $p=>$label){$pat=$s['patterns'][$p]??array();$map=array();foreach(($pat['map']??array()) as $k=>$v)$map[]=$k.'='.$v;$h.='<fieldset class="cm-pattern"><legend>پترن '.esc_html($label).'</legend><label>کد پترن<input name="'.$p.'_code" dir="ltr" value="'.esc_attr($pat['code']??'').'" maxlength="100"></label><div class="cm-grid"><label>متن پترن برای پیش‌نمایش<textarea name="'.$p.'_text" rows="4" maxlength="2000" placeholder="ولی گرامی {name}، …">'.esc_textarea($pat['text']??'').'</textarea></label><label>نگاشت متغیرها<textarea name="'.$p.'_map" dir="ltr" rows="4" placeholder="name=student&#10;school=school">'.esc_textarea(implode("\n",$map)).'</textarea></label></div></fieldset>';}
 $h.='<p class="cm-help">تمام پیامک‌ها فقط با انتخاب گیرنده، پیش‌نمایش و تأیید دستی مدیریت به شماره ولی ارسال می‌شوند.</p><button class="dg-btn">ذخیره اتصال و پترن‌ها</button></form>'.dgs_cm_form('credit',$year,array('section'=>'gateway')).'<button class="dg-btn dg-btn-outline">بررسی اتصال و اعتبار — بدون ارسال پیامک</button></form></section>';return $h;
}
function dgs_cm_school($year){$s=get_option('dgs_settings',array());return '<section class="cm-card"><h3>'.dgs_portal_icon('education').' اطلاعات مدرسه و سال تحصیلی</h3>'.dgs_cm_form('school',$year,array('section'=>'school','revision'=>$s['communication_revision']??0)).'<div class="cm-grid"><label>نام مدرسه<input name="school_name" value="'.esc_attr(dgs_setting('school_name','مدرسه دانشگران')).'" maxlength="100" required></label><label>کد مدرسه<input name="school_code" value="'.esc_attr($s['school_code']??'').'" dir="ltr" maxlength="30"></label><label>سال تحصیلی فعال<input name="school_year" value="'.esc_attr(dgs_edu_current_year()).'" dir="ltr" required></label><label>آغاز سال (شمسی)<input name="school_start" value="'.esc_attr($s['school_start']??'').'" dir="ltr" placeholder="1405-07-01"></label><label>پایان سال (شمسی)<input name="school_end" value="'.esc_attr($s['school_end']??'').'" dir="ltr" placeholder="1406-03-31"></label></div><p class="cm-help">تغییر سال فعال، سوابق سال‌های گذشته را حذف نمی‌کند. تاریخ‌ها اطلاعات تقویم مدرسه‌اند؛ مهلت نمرات از دفتر نمرات تنظیم می‌شود.</p><button class="dg-btn">ذخیره اطلاعات مدرسه</button></form></section>';}
function dgs_cm_compose($year){
 global $wpdb;$e=dgs_edu_tables();$classes=dgs_edu_classes($year);$options=dgs_edu_class_options($classes);$students=$wpdb->get_results($wpdb->prepare("SELECT u.ID,u.display_name,c.title FROM {$e['enrollments']} en JOIN {$wpdb->users} u ON u.ID=en.student_id JOIN {$e['classes']} c ON c.id=en.class_id WHERE en.school_year=%s AND c.active=1 ORDER BY u.display_name LIMIT 2000",$year));$studentOptions=array();foreach($students as $u)$studentOptions[$u->ID]=$u->display_name.' — '.$u->title;
 $s=dgs_cm_config();$credit=get_option('dgs_sms_credit',array());$h='<section class="cm-card cm-compose"><div class="cm-editor"><h3>'.dgs_portal_icon('message').' ارسال پیامک به اولیا</h3>'.dgs_cm_form('prepare',$year,array('request_token'=>wp_generate_uuid4())).'<fieldset class="cm-audience"><legend>نوع گیرنده:</legend>';foreach(array('individual'=>'فردی','class'=>'کلاسی','group'=>'گروهی') as $value=>$label)$h.='<label><input type="radio" name="audience" value="'.$value.'" '.checked($value,'class',false).'>'.$label.'</label>';$h.='</fieldset><div class="cm-grid"><div data-cm-scope="individual">'.dgs_edu_select('student_id','دانش‌آموز',$studentOptions,0,false).'</div><div data-cm-scope="class">'.dgs_edu_select('class_id','کلاس',$options,0,false).'</div><div data-cm-scope="group">'.dgs_mgmt_filter_select('grade','پایه',array(10=>'دهم',11=>'یازدهم',12=>'دوازدهم'),'','همه اولیای این سال').'</div>'.dgs_cm_select_purpose().'</div><div class="cm-grid"><label>ماه کارنامه (برای هدف کارنامه)<select name="period"><option value="">انتخاب ماه</option>';foreach(dgs_mg_periods($year) as $p=>$label)$h.='<option value="'.esc_attr($p).'">'.esc_html($label).'</option>';$h.='</select></label><label>تاریخ غیبت (برای هدف غیبت)<input name="day" dir="ltr" placeholder="1405-08-23"></label></div><label>توضیح پیام — متغیر message در پترن<textarea name="message" rows="5" maxlength="2000" data-cm-message placeholder="اگر پترن اطلاعیه متغیر message دارد، مقدار آن را وارد کنید."></textarea></label><p class="cm-help">برای کارنامه فقط دانش‌آموزان دارای کارنامه کامل منتشرشده و برای غیبت فقط غایبان همان روز انتخاب می‌شوند. ارسال به شماره ولیِ ثبت‌شده در پرونده است.</p><div class="cm-actions"><button class="dg-btn">'.dgs_portal_icon('eye').' پیش‌نمایش و انتخاب گیرندگان</button><a href="'.esc_url(dgs_cm_link($year,'gateway')).'">تنظیم پترن‌ها</a></div></form>'.dgs_cm_handset().'</div><aside class="cm-status"><h3>'.dgs_portal_icon('phone').' سامانه پیامک مدرسه</h3>'.'<span class="cm-badge">'.(!empty($s['enabled'])&&dgs_cm_key()?'ارسال فعال':'ارسال غیرفعال / اتصال ناقص').'</span>'.'<p>ارائه‌دهنده: <strong>IPPanel — پترن</strong></p><div class="cm-credit">اعتبار باقی‌مانده<strong>'.esc_html(isset($credit['value'])?dgs_fa_digits(number_format((float)$credit['value'],2)):'بررسی نشده').'</strong><small>واحد اعتبار IPPanel</small>'.(!empty($credit['at'])?'<small>'.esc_html(dgs_mg_display_date($credit['at'])).'</small>':'').'</div>'.dgs_cm_form('credit',$year).'<button class="dg-btn dg-btn-outline">به‌روزرسانی اعتبار</button></form><h4>گیرنده پیامک‌ها</h4><p>فقط اولیا · با تأیید دستی مدیریت</p><p class="cm-help">تعداد پیامک قابل خرید از روی اعتبار حدس زده نمی‌شود؛ تعرفه و بخش‌بندی نهایی را IPPanel محاسبه می‌کند.</p></aside></section>';return $h;
}
function dgs_cm_select_purpose(){return dgs_edu_select('purpose','هدف پیام',dgs_cm_purposes(),'notice');}
function dgs_cm_batch($id,$year){
 global $wpdb;$t=dgs_cm_tables();$batch=$wpdb->get_row($wpdb->prepare("SELECT * FROM {$t['batches']} WHERE id=%d",$id));if(!$batch)return '<p class="cm-card">ارسال پیدا نشد.</p>';$page=max(1,absint(dgs_att_get('cm_detail_page','1')));$total=(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$t['items']} WHERE batch_id=%d",$id));$pages=max(1,(int)ceil($total/25));$page=min($page,$pages);$rows=$wpdb->get_results($wpdb->prepare("SELECT i.*,u.display_name FROM {$t['items']} i LEFT JOIN {$wpdb->users} u ON u.ID=i.student_id WHERE batch_id=%d ORDER BY i.id LIMIT 25 OFFSET %d",$id,($page-1)*25));$counts=$wpdb->get_results($wpdb->prepare("SELECT status,COUNT(*) AS n FROM {$t['items']} WHERE batch_id=%d GROUP BY status",$id));$h='<section class="cm-card cm-batch"><h3>'.dgs_portal_icon('eye').' پیش‌نمایش و جزئیات ارسال '.esc_html(dgs_fa_digits($id)).'</h3><p>هدف: '.esc_html(dgs_cm_purposes()[$batch->purpose]??'').' · تعداد گیرندگان یکتا: '.esc_html(dgs_fa_digits($total)).'</p><div class="cm-counts">';foreach($counts as $c)$h.=dgs_cm_badge($c->status).' <b>'.esc_html(dgs_fa_digits($c->n)).'</b> ';$h.='</div>';
 if($batch->status==='draft'&&(int)$batch->actor_id===get_current_user_id())$h.='<p class="cm-help">پیش‌نمایش تا یک ساعت معتبر است. شماره‌های خالی ارسال نمی‌شوند؛ پیام‌های بیش از۲۴ساعت در صف لغو می‌شوند. متن واقعی و تعرفه را پترن تأییدشده IPPanel تعیین می‌کند.</p>'.dgs_cm_form('confirm',$year,array('batch_id'=>$id)).'<label class="cm-check"><input name="confirm_cost" type="checkbox" value="1" required> گیرندگان و متغیرها را بررسی کردم؛ ارسال با هزینه پنل تأیید می‌شود.</label><button class="dg-btn" data-cm-confirm="پیامک‌های این فهرست از IPPanel ارسال شوند؟">'.dgs_portal_icon('send').' تأیید و صف ارسال پیامک</button></form>';
 $h.='<p class="cm-help">پیش‌نمایش هر گیرنده، متغیرهای همان دانش‌آموز را دارد. تعداد بخش پیامک برآوردی است و تعرفه نهایی با IPPanel است.</p><div class="cm-table-scroll"><table class="cm-table"><thead><tr><th>دانش‌آموز</th><th>شماره ولی</th><th>وضعیت</th><th>جزئیات</th></tr></thead><tbody>';foreach($rows as $r){$payload=json_decode($r->payload_json,true);$h.='<tr><td>'.esc_html($r->display_name?:'حساب پیشین').'</td><td><bdi>'.esc_html(dgs_fa_digits($r->phone?:'—')).'</bdi></td><td>'.dgs_cm_badge($r->status).'</td><td><details><summary>مشاهده پیام و متغیرها</summary><div class="cm-phone"><p>'.nl2br(esc_html($r->preview)).'</p><small>'.esc_html(dgs_fa_digits(dgs_cm_units($r->preview)['units'])).' واحد نویسه · '.esc_html(dgs_fa_digits(dgs_cm_units($r->preview)['parts'])).' بخش تقریبی</small></div><p>کد پترن: <bdi>'.esc_html($payload['code']??'').'</bdi></p><dl>';foreach(($payload['params']??array()) as $k=>$v)$h.='<dt>'.esc_html($k).'</dt><dd>'.esc_html($v).'</dd>';$h.='</dl><small>شناسه پیگیری: '.esc_html($r->provider_id?:'—').' · نتیجه: '.esc_html(dgs_cm_error_label($r->error_code)).'</small></details></td></tr>';}$h.='</tbody></table></div><nav class="cm-pagination">';if($page>1)$h.='<a href="'.esc_url(dgs_cm_link($year,'sms',array('cm_batch'=>$id,'cm_detail_page'=>$page-1))).'">صفحه قبل</a>';$h.='<span>'.esc_html(dgs_fa_digits($page.' / '.$pages)).'</span>';if($page<$pages)$h.='<a href="'.esc_url(dgs_cm_link($year,'sms',array('cm_batch'=>$id,'cm_detail_page'=>$page+1))).'">صفحه بعد</a>';$h.='</nav><div class="cm-actions">'.dgs_cm_form('refresh',$year,array('batch_id'=>$id)).'<button class="dg-btn dg-btn-outline">استعلام وضعیت IPPanel</button></form>'.dgs_cm_form('process',$year,array('batch_id'=>$id)).'<button class="dg-btn dg-btn-outline">پردازش نوبت بعدی صف</button></form>'.dgs_cm_form('cancel',$year,array('batch_id'=>$id)).'<button class="dg-btn dg-btn-outline" data-cm-confirm="پیام‌های ارسال‌نشده لغو شوند؟">لغو پیام‌های ارسال‌نشده</button></form></div><p class="cm-help">پذیرفته‌شدن در درگاه، ارسال به اپراتور و تحویل به گوشی متفاوت‌اند. وضعیت نامشخص برای جلوگیری از هزینه تکراری خودکار تکرار نمی‌شود؛ آن را در IPPanel بررسی کنید.</p></section>';return $h;
}
function dgs_cm_history($year){global $wpdb;$t=dgs_cm_tables();$page=max(1,absint(dgs_att_get('cm_page','1')));$total=(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$t['batches']} WHERE school_year=%s",$year));$pages=max(1,(int)ceil($total/15));$page=min($page,$pages);$batches=$wpdb->get_results($wpdb->prepare("SELECT b.*,COUNT(i.id) AS recipients FROM {$t['batches']} b LEFT JOIN {$t['items']} i ON i.batch_id=b.id WHERE b.school_year=%s GROUP BY b.id ORDER BY b.id DESC LIMIT 15 OFFSET %d",$year,($page-1)*15));$h='<section class="cm-card"><h3>'.dgs_portal_icon('history').' سابقه ارسال پیامک‌ها</h3><div class="cm-table-scroll"><table class="cm-table"><thead><tr><th>ردیف</th><th>تاریخ و ساعت</th><th>موضوع</th><th>گیرندگان</th><th>وضعیت</th><th>تعداد</th><th>جزئیات</th></tr></thead><tbody>';foreach($batches as $b){$counts=$wpdb->get_results($wpdb->prepare("SELECT status,COUNT(*) AS n FROM {$t['items']} WHERE batch_id=%d GROUP BY status",$b->id));$h.='<tr><td>'.esc_html(dgs_fa_digits($b->id)).'</td><td>'.esc_html(dgs_mg_display_date($b->created_at)).'</td><td>'.esc_html(dgs_cm_purposes()[$b->purpose]??'').'</td><td>'.esc_html(array('class'=>'کلاسی','group'=>'گروهی','individual'=>'فردی')[$b->audience]??$b->audience).'</td><td>';foreach($counts as $c)$h.=dgs_cm_badge($c->status).' '.esc_html(dgs_fa_digits($c->n)).' ';$h.='</td><td>'.esc_html(dgs_fa_digits($b->recipients)).'</td><td><a href="'.esc_url(dgs_cm_link($year,'sms',array('cm_batch'=>$b->id))).'">'.dgs_portal_icon('eye').' مشاهده</a></td></tr>';}if(!$batches)$h.='<tr><td colspan="7">هنوز ارسالی ثبت نشده است.</td></tr>';$h.='</tbody></table></div><nav class="cm-pagination">';if($page>1)$h.='<a href="'.esc_url(dgs_cm_link($year,'sms',array('cm_page'=>$page-1))).'">صفحه قبل</a>';$h.='<span>'.esc_html(dgs_fa_digits($page.' / '.$pages)).'</span>';if($page<$pages)$h.='<a href="'.esc_url(dgs_cm_link($year,'sms',array('cm_page'=>$page+1))).'">صفحه بعد</a>';return $h.'</nav></section>';}
function dgs_edu_view_communication($year){
 if(!dgs_manage_allowed())return '';$section=dgs_att_get('cm_section','sms');if(!in_array($section,array('sms','users','school','gateway'),true))$section='sms';$h='<div class="cm-page"><header class="cm-heading"><h2>'.dgs_portal_icon('message').' ارتباط با اولیا و تنظیمات</h2></header><nav class="cm-tabs">';foreach(array('sms'=>'پیامک اولیا','users'=>'کاربران و دسترسی','school'=>'تنظیمات مدرسه','gateway'=>'اتصال IPPanel') as $key=>$label)$h.='<a '.($key===$section?'aria-current="page"':'').' href="'.esc_url(dgs_cm_link($year,$key)).'">'.dgs_portal_icon(array('sms'=>'message','users'=>'users','school'=>'education','gateway'=>'lock')[$key]).esc_html($label).'</a>';$h.='</nav>';
 if($section==='gateway')$h.=dgs_cm_gateway($year);elseif($section==='users')$h.='<section class="cm-card"><h3>کاربران و دسترسی‌های موجود سامانه</h3><p>مدیر و معاون: مدیریت آموزشی؛ دبیر: کلاس‌ها و درس‌های تخصیص‌یافته؛ مشاور: دانش‌آموزان تخصیص‌یافته؛ دانش‌آموز: اطلاعات خودش. اتصال پیامک فقط توسط مدیر اصلی تنظیم می‌شود.</p></section>'.dgs_edu_view_users($year);elseif($section==='school')$h.=dgs_cm_school($year);else{$h.=dgs_cm_compose($year);$batch=absint(dgs_att_get('cm_batch'));if($batch)$h.=dgs_cm_batch($batch,$year);$h.=dgs_cm_history($year);$h.='<div class="cm-bottom"><section class="cm-card"><h3>'.dgs_portal_icon('education').' اطلاعات مدرسه</h3><p>'.esc_html(dgs_setting('school_name','مدرسه دانشگران')).'</p><p>دوره دوم متوسطه · پایه‌های دهم، یازدهم و دوازدهم</p><a href="'.esc_url(dgs_cm_link($year,'school')).'">ویرایش اطلاعات مدرسه</a></section><section class="cm-card"><h3>'.dgs_portal_icon('timetable').' سال تحصیلی و تقویم</h3><strong>'.esc_html(dgs_fa_digits(dgs_edu_current_year())).'</strong><p>آغاز: '.esc_html(dgs_fa_digits(dgs_setting('school_start','تعیین نشده'))).'</p><p>پایان: '.esc_html(dgs_fa_digits(dgs_setting('school_end','تعیین نشده'))).'</p><a href="'.esc_url(dgs_cm_link($year,'school')).'">تنظیم تقویم مدرسه</a></section><section class="cm-card"><h3>'.dgs_portal_icon('users').' نقش‌ها و دسترسی‌ها</h3><p>مدیر و معاون · دبیر · مشاور · دانش‌آموز</p><a href="'.esc_url(dgs_cm_link($year,'users')).'">مدیریت کاربران موجود</a></section></div>';}
 return $h.'</div>';
}
add_filter('body_class',function($c){if(dgs_is_role_portal()&&dgs_portal_tab()==='communication')$c[]='dgs-communication';return $c;});
add_action('wp_enqueue_scripts',function(){if(!dgs_is_role_portal()||dgs_portal_tab()!=='communication')return;wp_enqueue_style('dgs-communication',DGS_URL.'assets/communication.css',array(),DGS_VERSION);wp_enqueue_script('dgs-communication',DGS_URL.'assets/communication.js',array(),DGS_VERSION,true);},65);

function dgs_cm_handset(){
 $s=dgs_cm_config();$patterns=array();foreach(dgs_cm_purposes() as $purpose=>$label){$p=$s['patterns'][$purpose]??array();$patterns[$purpose]=array('text'=>$p['text']??'','map'=>$p['map']??array());}
 return '<div class="cm-preview"><h4>پیش‌نمایش پترن</h4><div class="cm-phone"><p data-cm-preview>پترن را تنظیم و هدف پیام را انتخاب کنید.</p></div><small data-cm-parts></small><p class="cm-help">گیرندگان و متغیرهای واقعی در مرحله بعد نمایش داده می‌شوند.</p></div><script type="application/json" id="cm-pattern-data">'.wp_json_encode($patterns,JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT).'</script>';
}

function dgs_cm_error_label($code){
